    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignInScreen.tsx",
      "issue": "Form implementation details are not visible. It is unclear whether email/password fields have labels above inputs, appropriate autocomplete attributes, a show/hide password toggle, live validation, and inline error messages as required.",
