    },
    {
      "severity": "medium",
      "file": "expo-app/src/screens/SignUpScreen.tsx",
      "issue": "Same uncertainty as SignInScreen – missing evidence of required accessibility and validation features (labels, autocomplete, password rule helper, show/hide toggle, inline errors, non‑silently disabled submit).",
