{"path": "expo-app/src/screens/ReceiptCaptureScreen.tsx", "content": "import React, { useState, useRef } from 'react';
import { View, Text, TextInput, ActivityIndicator, Alert, StyleSheet, Image, ScrollView, Platform, Pressable } from 'react-native';
import * as ImagePicker from 'expo-image-picker';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/PrimaryButton';

export default function ReceiptCaptureScreen() {
  const navigation = useNavigation<any>();
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [image, setImage] = useState<any>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<any>(null);

  const requestPermission = async () => {
    const { status } = await ImagePicker.requestCameraPermissionsAsync();
    setHasPermission(status === 'granted');
  };

  const pickImage = async () => {
    // Use expo-image-picker for native platforms, file input for web
    if (Platform.OS === 'web') {
      // This will be triggered via hidden input, handled in onFileChange
      return;
    }
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      quality: 1,
    });
    if (!result.canceled) {
      setImage(result);
    }
  };

  const takePhoto = async () => {
    const result = await ImagePicker.launchCameraAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      quality: 1,
    });
    if (!result.canceled) {
      setImage(result);
    }
  };

  const handleFileChange = (e: any) => {
    const file = e.target.files[0];
    if (file) {
      const uri = URL.createObjectURL(file);
      setImage({ assets: [{ uri, name: file.name, type: file.type }] });
    }
  };

  const handlePlaceholderPress = () => {
    if (Platform.OS === 'web') {
      fileInputRef.current?.click();
    } else {
      // Prefer camera first, fallback to library if needed
      pickImage();
    }
  };

  const handleSave = async () => {
    if (!amount || !date || !category) {
      Alert.alert('Error', 'Please fill all required fields.');
      return;
    }
    setLoading(true);
    try {
      const token = await getToken();
      const form = new FormData();
      form.append('amount', amount);
      form.append('date', date);
      form.append('category', category);
      form.append('notes', notes);
      if (image) {
        if (Platform.OS === 'web') {
          const resp = await fetch(image.assets[0].uri);
          const blob = await resp.blob();
          form.append('image', blob, image.assets[0].name || 'receipt.jpg');
        } else {
          (form as any).append('image', {
            uri: image.assets[0].uri,
            name: image.assets[0].name || 'receipt.jpg',
            type: image.assets[0].type || 'image/jpeg',
          } as any);
        }
      } else {
        // Fallback placeholder image if none selected
        const placeholder = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/5+hHgAFgwJ/9YX8WAAAAABJRU5ErkJggg==';
        if (Platform.OS === 'web') {
          const resp = await fetch(placeholder);
          const blob = await resp.blob();
          form.append('image', blob, 'receipt.jpg');
        } else {
          (form as any).append('image', {
            uri: placeholder,
            name: 'receipt.jpg',
            type: 'image/png',
          } as any);
        }
      }
      await axios.post(`${API_URL}/receipts`, form, {
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'multipart/form-data' },
      });
      navigation.navigate('Dashboard', { receiptSaved: true });
    } catch (e) {
      Alert.alert('Error', 'Upload failed. Check your connection and try again.');
    } finally {
      setLoading(false);
    }
  };

  if (hasPermission === false) {
    return (
      <ScrollView contentContainerStyle={styles.container} accessibilityRole="none">
        <Text style={styles.text}>Camera access denied. You can select a photo from the library.</Text>
        <PrimaryButton title="Choose from library" onPress={pickImage} accessibilityLabel="Choose from library" />
        {renderForm()}
      </ScrollView>
    );
  }

  if (hasPermission === null) {
    return (
      <View style={styles.container} accessibilityRole="none">
        <Text style={styles.heading}>New receipt</Text>
        <Text style={styles.text}>Camera access needed</Text>
        <PrimaryButton title="Allow" onPress={requestPermission} accessibilityLabel="Allow" />
        <PrimaryButton title="Deny" onPress={() => setHasPermission(false)} accessibilityLabel="Deny" />
      </View>
    );
  }

  function renderForm() {
    return (
      <View style={styles.form}>
        <Text style={styles.heading}>New receipt</Text>
        {image && <Image source={{ uri: image.assets[0].uri }} style={styles.image} />}
        {/* Placeholder when no image selected */}
        {!image && (
          <Pressable
            onPress={handlePlaceholderPress}
            accessibilityRole="button"
            accessibilityLabel="Tap to take a photo or choose from library"
            style={styles.placeholderContainer}
          >
            <Text style={styles.placeholderText}>Tap to take a photo or choose from library</Text>
            {/* Hidden file input for web */}
            {Platform.OS === 'web' && (
              <input
                type="file"
                accept="image/*"
                ref={fileInputRef}
                style={{ display: 'none' }}
                onChange={handleFileChange}
              />
            )}
          </Pressable>
        )}
        {/* Keep explicit actions for native platforms */}
        {Platform.OS !== 'web' && (
          <>
            <PrimaryButton title="Take photo" onPress={takePhoto} accessibilityLabel="Take photo" />
            <PrimaryButton title="Choose from library" onPress={pickImage} accessibilityLabel="Choose from library" />
          </>
        )}
        <Text style={styles.fieldLabel} nativeID="amount-label">Amount (USD)</Text>
        <TextInput
          nativeID="amount-input"
          testID="amount-input"
          placeholder="Amount (USD)"
          value={amount}
          onChangeText={setAmount}
          style={styles.input}
          accessibilityLabel="Amount (USD)"
          accessibilityLabelledBy="amount-label"
